  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
});

test('issueInvoice generates correct invoice number based on existing numbers', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-06-30',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002'];
  const result = issueInvoice(invoice, existingNumbers);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0003');
});

test('issueInvoice handles different years correctly', () => {
  const invoice2023 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-12-31',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const invoice2024 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existingNumbers = ['INV-2023-9999'];

  const result2023 = issueInvoice(invoice2023, existingNumbers);
  assert.equal(result2023.value.number, 'INV-2023-10000');

  const result2024 = issueInvoice(invoice2024, existingNumbers);
