  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 5 * 8500 = 42500
  // discount: 42500 * 10% = 4250
  // after discount: 42500 - 4250 = 38250
  // vat: 38250 * 21% = 8032.5 ≈ 8033
  // total: 42500 - 4250 + 8033 = 46283
  assert.deepEqual(totals, { subtotal: 42500, discount: 4250, vat: 8033, total: 46283 });
});

