});

test('addLine reports QTY_INVALID for zero quantity', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 0 });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('addLine reports UNKNOWN_SKU for unknown product', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
