test('removeLine removes a line from an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const result = removeLine(invoice, 'DES-HOUR');
  assert.equal(result.ok, true);
