test('removeLine preserves all invoice properties', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-06-30',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const result = removeLine(invoice, 'DES-HOUR');
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2024-06-30');
  assert.equal(result.value.status, 'draft');
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0001');
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
});

test('issueInvoice generates correct invoice number based on existing numbers', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-06-30',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002'];
  const result = issueInvoice(invoice, existingNumbers);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0003');
});

test('issueInvoice handles different years correctly', () => {
  const invoice2023 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-12-31',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const invoice2024 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existingNumbers = ['INV-2023-9999'];

  const result2023 = issueInvoice(invoice2023, existingNumbers);
  assert.equal(result2023.value.number, 'INV-2023-10000');

  const result2024 = issueInvoice(invoice2024, existingNumbers);
  assert.equal(result2024.value.number, 'INV-2024-0001');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const before = JSON.stringify(invoice);
  issueInvoice(invoice, []);
  assert.equal(JSON.stringify(invoice), before);
});

test('issueInvoice returns copies of lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result1 = issueInvoice(invoice, []);
  const result2 = issueInvoice(invoice, []);

  // Mutate first result's line
  result1.value.lines[0].qty = 999;

  // Second result should be unaffected
  assert.equal(result2.value.lines[0].qty, 5);
});

test('createInvoice accepts discountPercent on lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice applies tier discount to lines without explicit discount', () => {
  const result = createInvoice({
